use compositor_engine::*;
use uuid::Uuid;
fn source(hdr:bool)->Raster{if hdr{Raster::from_rgba_float(16,16,(0..256).flat_map(|i|[2.+i as f32/256.,3.,4.,1.]).collect())}else{Raster::from_rgba16(16,16,(0..256).flat_map(|i|[12345+i,23456+i,34567+i,65535]).collect())}}
fn setup(hdr:bool)->(Engine,Uuid,Uuid,Raster){let raster=source(hdr);let mut d=Document::new(16,16);let l=Layer::with_pixels("Deep",raster.clone(),Point{x:0.,y:0.});let id=l.id;d.active_layer_id=Some(id);d.layers.push(l);let mut e=Engine::new();let doc=e.insert_document(d);(e,doc,id,raster)}
fn select(e:&mut Engine,doc:Uuid,x:f64,y:f64,w:f64,h:f64){e.execute(doc,Command::SelectShape{kind:SelectionShape::Rectangle,points:vec![Point{x,y},Point{x:x+w,y},Point{x:x+w,y:y+h},Point{x,y:y+h}],mode:SelectionMode::Replace,antialiased:false}).unwrap();}
#[test]fn clear_keeps_unselected_precise_samples_and_undo(){for hdr in [false,true]{let(mut e,doc,id,original)=setup(hdr);select(&mut e,doc,2.,2.,3.,3.);e.execute(doc,Command::ClearSelectedPixels{id,mask:false}).unwrap();let r=e.document(doc).unwrap().layer(id).unwrap().pixels.as_ref().unwrap();assert_eq!(r.depth(),original.depth());assert_eq!(r.pixel_f32(3,3),[0.;4]);assert_eq!(&r.deep_pixels().unwrap().samples[..64],&original.deep_pixels().unwrap().samples[..64]);e.undo(doc).unwrap();assert_eq!(e.document(doc).unwrap().layer(id).unwrap().pixels.as_ref().unwrap().deep_pixels(),original.deep_pixels());}}
#[test]fn floating_copy_keeps_sub_byte_colors_and_hdr_light_when_merged(){for hdr in [false,true]{let(mut e,doc,id,original)=setup(hdr);select(&mut e,doc,2.,2.,2.,2.);let floating=e.begin_floating(doc,id,true).unwrap();let mut t=e.document(doc).unwrap().layer(floating).unwrap().transform;t.origin.x+=6.;e.commit_floating(doc,t,None).unwrap();let r=e.document(doc).unwrap().layer(id).unwrap().pixels.as_ref().unwrap();assert_eq!(r.depth(),original.depth());assert_eq!(r.pixel_f32(8,2),original.pixel_f32(2,2));assert_eq!(r.pixel_f32(2,2),original.pixel_f32(2,2));e.undo(doc).unwrap();assert_eq!(e.document(doc).unwrap().layer(id).unwrap().pixels.as_ref().unwrap().deep_pixels(),original.deep_pixels());}}
#[test]fn perspective_identity_and_stretch_keep_precision(){for hdr in [false,true]{let r=source(hdr);let t=LayerTransform::axis_aligned(Point{x:0.,y:0.},Size{width:16.,height:16.});let(out,_)=ops::distort::warp(&r,&t,&t.corners(),false).unwrap();assert_eq!(out.deep_pixels(),r.deep_pixels());let mut corners=t.corners();corners[1].x+=8.;corners[2].x+=8.;let(out,_)=ops::distort::warp(&r,&t,&corners,false).unwrap();assert_eq!(out.depth(),r.depth());assert!(out.deep_pixels().unwrap().samples.chunks_exact(4).any(|p|if hdr{half::f16::from_bits(p[0]).to_f32()>1.}else{p[0]%257!=0}));}}
#[test]fn byte_based_retouch_keeps_deep_values_outside_its_footprint(){for content_fill in [false,true]{let(mut e,doc,id,original)=setup(false);if content_fill{select(&mut e,doc,6.,6.,2.,2.);e.execute(doc,Command::ContentAwareFill{id}).unwrap();}else{e.execute(doc,Command::WarpStroke{id,mask:false,warp:WarpSpec{mode:warp::WarpMode::Smudge,diameter:2.,hardness:0.5,strength:0.5,points:vec![Point{x:6.,y:8.},Point{x:9.,y:8.}]}}).unwrap();}let r=e.document(doc).unwrap().layer(id).unwrap().pixels.as_ref().unwrap();assert_eq!(r.depth(),PixelDepth::Sixteen);assert_eq!(r.pixel_f32(0,0),original.pixel_f32(0,0));assert_eq!(r.pixel_f32(15,15),original.pixel_f32(15,15));}}
